css:
:root{--bg:#fff;--fg:#17181a;--dim:#6b6f76;--card:#f3f3f1;--line:#d9d9d4;--ok:#0a7d33;--bad:#b3261e;--btn:#17181a;--btnfg:#fff;--on:#0a7d33;--off:#b9bbbf}
@media (prefers-color-scheme:dark){:root{--bg:#0f1013;--fg:#f0f0f0;--dim:#9a9da3;--card:#17181b;--line:#2a2b2f;--ok:#4ade80;--bad:#f87171;--btn:#eab308;--btnfg:#111;--on:#eab308;--off:#3a3c42}}
html,body{background:var(--bg);color:var(--fg)}
.wrap{padding:12px 12px 24px}
.mod{margin:0 0 14px}
.mod>h2{font-size:11px;letter-spacing:.06em;color:var(--dim);margin:0 0 4px;font-weight:700}
.sw{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--line)}
.sw .info{flex:1;min-width:0}
.sw .t{font-size:12px;font-weight:700}
.sw .d{font-size:10.5px;color:var(--dim);margin-top:2px;word-break:break-word}
.tg{position:relative;width:44px;height:26px;flex:0 0 auto}
.tg input{opacity:0;position:absolute;left:0;top:0;width:100%;height:100%;margin:0;z-index:2}
.tg i{position:absolute;left:0;top:0;right:0;bottom:0;border-radius:13px;background:var(--off);transition:background .15s}
.tg i:after{content:'';position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:#fff;transition:transform .15s}
.tg input:checked+i{background:var(--on)}
.tg input:checked+i:after{transform:translateX(18px)}
.row{display:flex;gap:6px;margin:8px 0}
button{flex:1;background:var(--btn);color:var(--btnfg);border:0;border-radius:8px;padding:9px 6px;font-size:11px;font-weight:600}
button.alt{background:var(--card);color:var(--fg);border:1px solid var(--line)}
button.sm{flex:0 0 auto;padding:6px 8px}
.comp{font-size:10px;color:var(--dim);margin:4px 0 0;word-break:break-word}
.err{background:var(--card);border:1px solid var(--bad);color:var(--bad);border-radius:8px;padding:8px;font:11px/1.4 monospace;white-space:pre-wrap}
pre{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:8px;font:10.5px/1.45 monospace;white-space:pre-wrap;word-break:break-word;margin:6px 0 0}
details>summary{font-size:11px;font-weight:700;color:var(--dim);padding:6px 0}
.foot{margin-top:6px}
.ver{font-size:10px;color:var(--dim);text-align:center;margin-top:6px}
details>summary{cursor:pointer}
.hint{font-size:10.5px;line-height:1.45;color:var(--dim);margin:0 0 10px}.hint.warn{color:var(--bad)}
.lbl{font-size:10px;font-weight:700;letter-spacing:.05em;color:var(--dim);margin:6px 0 4px;text-transform:uppercase}
.bmsg{font-size:11px;min-height:14px;margin-top:6px;color:var(--dim)}.bmsg.ok{color:var(--ok)}.bmsg.err{color:var(--bad)}
.zt-seg{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}.zt-seg button{flex:1 1 22%;padding:9px 4px}
.zt-seg button.on{background:var(--btn);color:var(--btnfg);border-color:var(--btn)}
.zt-card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin:8px 0}
.zt-title{font-size:12px;font-weight:800}.zt-sub{font-size:10.5px;color:var(--dim);margin-top:1px}
.zt-sum{font-size:10.5px;color:var(--dim);line-height:1.6;margin-top:6px;word-break:break-word}
.zt-row{display:flex;align-items:center;gap:6px;margin-top:8px;flex-wrap:wrap}.zt-row label{font-size:11px;color:var(--dim);flex:1 1 90px}
.zt-in{flex:none;width:54px;text-align:center;padding:7px 2px;background:var(--bg);border:1px solid var(--line);border-radius:6px;color:var(--fg);font-size:12px;font-weight:600}
.zt-u{font-size:11px;color:var(--dim)}
.zt-warn{display:none;margin-top:10px;padding:8px 10px;border:1px solid #fb923c;border-radius:8px;color:#c2410c;font-size:11px;line-height:1.5}
.zt-info{display:none;margin-top:8px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;color:var(--dim);font-size:11px;line-height:1.5}
.beh-card{border:1.5px solid var(--line);border-radius:12px;background:var(--card);padding:10px;margin:0 0 8px}
.beh-card.on{border-color:#eab308;box-shadow:0 0 0 2px rgba(234,179,8,.18)}
.beh-top{display:flex;align-items:center;gap:8px}.beh-ic{font-size:18px;line-height:1}
.beh-name{font-size:12px;font-weight:800;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.beh-tag{font-size:9px;font-weight:700;padding:2px 7px;border-radius:99px;background:#eab308;color:#17181a}
.beh-tag.mod{background:transparent;border:1px solid #eab308;color:#ca8a04}
.beh-desc{font-size:10.5px;line-height:1.45;color:var(--dim);margin:6px 0}
.beh-chips{display:flex;flex-wrap:wrap;gap:4px;margin:6px 0 8px}
.beh-chip{font-size:9.5px;font-weight:600;padding:2px 7px;border-radius:99px;background:var(--bg);border:1px solid var(--line)}
.beh-btns{display:flex;gap:6px;flex-wrap:wrap}
.beh-b{flex:0 0 auto;padding:7px 11px;font-size:10.5px;background:var(--bg);color:var(--fg);border:1.5px solid var(--line)}
.beh-b.pri{background:#eab308;border-color:#eab308;color:#17181a}.beh-b.del{color:var(--bad)}.beh-b:disabled{opacity:.55}
.beh-in{width:100%;box-sizing:border-box;margin:6px 0;padding:8px;background:var(--bg);color:var(--fg);border:1px solid var(--line);border-radius:6px;font-size:12px}
.tg-btns{display:flex;gap:6px;margin-top:8px}.tg-btns button{padding:9px 4px}.tg-btns .del{color:var(--bad)}
label.tg-file{flex:1;display:block;text-align:center;border-radius:8px;padding:9px 6px;font-size:11px;font-weight:600;background:var(--card);color:var(--fg);border:1px solid var(--line);cursor:pointer}
textarea.beh-in{resize:vertical;font:11px/1.4 monospace}
button.del{color:var(--bad)}
.pd-stats{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}
.pd-stat{flex:1;min-width:70px;background:var(--card);border:1px solid var(--line);border-radius:8px;padding:6px 8px;text-align:center}
.pd-stat b{display:block;font-size:15px}.pd-stat span{font-size:9px;color:var(--dim);letter-spacing:.04em}
.pd-list{max-height:180px;overflow:auto;border:1px solid var(--line);background:var(--card);border-radius:8px;padding:0 8px;margin:4px 0}
.pd-li{display:flex;justify-content:space-between;gap:6px;font-size:11px;padding:5px 0;border-top:1px solid var(--line)}.pd-li:first-child{border-top:0}
.pd-li a{color:var(--fg);font-weight:600;text-decoration:none;word-break:break-all}.pd-li span{color:var(--dim);white-space:nowrap}
#pdFilter button.on{background:var(--btn);color:var(--btnfg);border-color:var(--btn)}
.chips{display:flex;flex-wrap:wrap;gap:6px}
button.chip{flex:0 0 auto;padding:7px 11px}
button.chip.on{background:var(--btn);color:var(--btnfg);border-color:var(--btn)}
.ps-warn{display:none;background:var(--card);border:1.5px solid #fb923c;color:#c2410c;border-radius:10px;padding:9px 12px;font-size:11px;font-weight:700;line-height:1.5;margin:0 0 8px;white-space:pre-wrap}
.ps-cnt{font-size:10px;font-weight:700;color:var(--dim);text-align:right;margin-top:3px}.ps-cnt.over{color:var(--bad)}

