  const q = (f) => { const x = card.querySelector('[data-f="' + f + '"]'); const n = x ? parseInt(x.value, 10) : 0; return isFinite(n) && n >= 0 ? n : 0; };
  const f = i.dataset.f;
  if (f === 'perM' || f === 'perS') c.per = Math.max(1, q('perM') * 60 + q('perS'));
  else if (f === 'n') c.n = Math.max(1, q('n'));
  else if (f === 'totH' || f === 'totM') c.totalSec = Math.max(60, q('totH') * 3600 + q('totM') * 60);
  else if (f === 'breakEvery') c.breakEvery = q('breakEvery');
  else if (f === 'bMin') c.bMin = q('bMin');
  else if (f === 'bMax') c.bMax = q('bMax');
  save(false); refreshGroup(gk);
});
zx.storage.onChanged((ch) => {
  if (!ch[KEY]) return;
  const nv = merge(ch[KEY].newValue);
  if (JSON.stringify(nv) === JSON.stringify(cfg)) return;
  cfg = nv; resolved = resolveAll(); if (!sec.querySelector('#tmBox').open || !host.contains(document.activeElement)) render();
});
// used by the Behaviour module (profiles switch every group at once)
window.__ZXT = { applyProfile: (t) => { cfg = merge(t); const p = save(true); render(); return p; }, merge: merge, resolveAll: resolveAll, _cfg: () => cfg };
return zx.storage.get([KEY]).then((d) => { cfg = merge(d[KEY]); resolved = resolveAll(); render(); return zx.storage.set({ [RES]: resolved }).catch(() => {}); });

};
ZXMODS["wallchain"] = function (zx, sec) {
