  ['SEARCH', [['searchFollow', 'FOLLOW BY WALLCHAIN SCORE', FOL, 'follow'], ['searchCollect', 'COLLECT USERNAME BY WALLCHAIN WHILE ENGAGING', COLS, 'range'], ['searchEngage', 'ENGAGE BY WALLCHAIN SCORE', 'Score outside the range = no SEA button on that post.', 'range']]],
